// Generated by esquadro: do not edit. Who changed what, and when: a
// record's history on its page, and every change for those who administer.
import { keepPreviousData, useQuery } from "@tanstack/react-query"
import { Link, useNavigate, useSearch } from "@tanstack/react-router"
import { ArrowRight, Bot, ChevronDown, ChevronLeft, ChevronRight, History as HistoryIcon, KeyRound, Pencil, Plus, RotateCcw, Trash2 } from "../icons.gen.ts"
import { useState } from "react"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Skeleton } from "@/components/ui/skeleton"
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table"
import { cn } from "@/lib/utils"
import { api } from "../api.ts"
import { locale } from "../config.ts"
import { resources } from "../resources.gen.ts"
import { auditAdmins } from "../accounts.gen.ts"
import { allowedBy, seen } from "./accounts-admin.tsx"
import { capitalize, t } from "./i18n.ts"
import type { FieldMeta, Rec, ResourceMeta } from "./meta.ts"
import { PageHeader } from "./page.tsx"
import { initials } from "./picture.tsx"
import { FieldValue } from "./show.tsx"
import { ErrorState, StateView } from "./states.tsx"

type Action = "create" | "update" | "delete" | "restore" | "purge"

interface Entry {
  id: string
  at: string
  entity: string
  record_id: string
  action: Action
  actor: { kind: "person" | "service" | "system"; realm?: string; id?: string; name: string }
  changes: Record<string, { from?: unknown; to?: unknown; secret?: boolean }>
}

interface EntryPage {
  items: Entry[]
  page: number
  total: number
  total_pages: number
}

const PER_PAGE = 20

const ACTIONS: Record<Action, { icon: typeof Plus; tone: string }> = {
  create: { icon: Plus, tone: "bg-emerald-500/15 text-emerald-600 dark:text-emerald-400" },
  update: { icon: Pencil, tone: "bg-sky-500/15 text-sky-600 dark:text-sky-400" },
  delete: { icon: Trash2, tone: "bg-amber-500/15 text-amber-600 dark:text-amber-400" },
  restore: { icon: RotateCcw, tone: "bg-violet-500/15 text-violet-600 dark:text-violet-400" },
  purge: { icon: Trash2, tone: "bg-destructive/15 text-destructive" },
}

/** The resource of an audited entity (by its plural: products). */
function metaOfEntity(entity: string): ResourceMeta | undefined {
  return Object.values(resources as unknown as Record<string, ResourceMeta>).find((m) => m.history?.entity === entity)
}

/** A field of a change, as its resource has it; its name otherwise. */
function fieldOf(meta: ResourceMeta | undefined, name: string): FieldMeta {
  return meta?.fields[name] ?? { name, label: capitalize(name.replaceAll("_", " ")), kind: "text", required: false }
}

const when = (at: string) => new Date(at).toLocaleString(locale, { dateStyle: "medium", timeStyle: "short" })

/** Who made a change: their initials, a key or the system. */
function ActorBadge({ actor }: { actor: Entry["actor"] }) {
  return (
    <span className="flex size-9 shrink-0 items-center justify-center rounded-full bg-primary/10 text-xs font-bold text-primary">
      {actor.kind === "person" ? initials(actor.name || "?") : actor.kind === "service" ? <KeyRound className="size-4" /> : <Bot className="size-4" />}
    </span>
  )
}

/** What happened to each field: before → after, or only that it changed. */
function Changes({ meta, entry }: { meta: ResourceMeta | undefined; entry: Entry }) {
  const fields = Object.entries(entry.changes)
  if (fields.length === 0) return null
  return (
    <dl className="mt-2 grid gap-1.5 rounded-lg border border-border bg-muted/40 p-3 text-sm">
      {fields.map(([name, c]) => {
        const field = fieldOf(meta, name)
        return (
          <div key={name} className="flex flex-wrap items-center gap-x-2 gap-y-1">
            <dt className="min-w-28 font-semibold text-foreground">{field.label}</dt>
            <dd className="flex flex-wrap items-center gap-2 text-muted-foreground">
              {c.secret ? (
                <span className="italic">{t("changedSecret")}</span>
              ) : (
                <>
                  {entry.action === "update" && (
                    <>
                      <span className="line-through decoration-muted-foreground/50">
                        <FieldValue field={field} record={{ id: "", version: 0, [name]: c.from ?? null } as never} />
                      </span>
                      <ArrowRight className="size-3.5" />
                    </>
                  )}
                  <span className="text-foreground">
                    <FieldValue field={field} record={{ id: "", version: 0, [name]: (entry.action === "update" || entry.action === "create" ? c.to : c.from) ?? null } as never} />
                  </span>
                </>
              )}
            </dd>
          </div>
        )
      })}
    </dl>
  )
}

/** A change, in words: Ana changed 2 fields. */
function sentence(entry: Entry): string {
  const count = Object.keys(entry.changes).length
  if (entry.action === "update") return t("auditUpdated", { count })
  return t(`audit_${entry.action}`)
}

/** Whether the session sees a record's history: who may change it, read it, or the admins. */
export function seesHistory(meta: ResourceMeta, record: Rec, session: { realm: string; roles: string[] } | null): boolean {
  switch (meta.history?.who) {
    case undefined:
      return false
    case "update":
      return (record.can ?? []).includes("update")
    case "admins":
      return allowedBy(session, auditAdmins ?? [])
  }
  return true
}

/** A record's history, on its page: its changes, the newest first. */
export function RecordHistory({ meta, id }: { meta: ResourceMeta; id: string }) {
  const [page, setPage] = useState(1)
  const history = useQuery({
    queryKey: [meta.name, "history", id, page],
    queryFn: ({ signal }) =>
      (meta.api(api as never) as unknown as { history(id: string, q: object, o: object): Promise<EntryPage> }).history(id, { page, per_page: PER_PAGE }, { signal }),
    placeholderData: keepPreviousData,
  })
  if (history.isError) return <ErrorState error={history.error} onRetry={() => history.refetch()} />
  if (history.isPending) return <Skeleton className="h-40 w-full" />
  const items = history.data.items
  if (items.length === 0) return <StateView icon={<HistoryIcon />} title={t("noHistory")} description={t("noHistoryHint")} />
  return (
    <div className="flex flex-col gap-4">
      <ol className="relative flex flex-col gap-6 border-l border-border pl-6">
        {items.map((e) => {
          const A = ACTIONS[e.action]
          return (
            <li key={e.id} className="relative">
              <span className={cn("absolute -left-[2.15rem] flex size-6 items-center justify-center rounded-full ring-4 ring-card", A.tone)}>
                <A.icon className="size-3.5" />
              </span>
              <div className="flex items-start gap-3">
                <ActorBadge actor={e.actor} />
                <div className="min-w-0 flex-1">
                  <p className="text-sm">
                    <span className="font-semibold text-foreground">{e.actor.name}</span> <span className="text-muted-foreground">{sentence(e)}</span>
                  </p>
                  <p className="text-xs text-muted-foreground" title={when(e.at)}>
                    {seen(e.at)}
                  </p>
                  <Changes meta={meta} entry={e} />
                </div>
              </div>
            </li>
          )
        })}
      </ol>
      {history.data.total_pages > 1 && (
        <Pager page={page} pages={history.data.total_pages} onPage={setPage} />
      )}
    </div>
  )
}

function Pager({ page, pages, onPage }: { page: number; pages: number; onPage: (p: number) => void }) {
  return (
    <div className="flex items-center justify-end gap-1 text-sm">
      <Button variant="ghost" size="icon-sm" disabled={page <= 1} aria-label={t("previous")} onClick={() => onPage(page - 1)}>
        <ChevronLeft />
      </Button>
      <span className="px-2 font-semibold tabular-nums">
        {page} / {pages}
      </span>
      <Button variant="ghost" size="icon-sm" disabled={page >= pages} aria-label={t("next")} onClick={() => onPage(page + 1)}>
        <ChevronRight />
      </Button>
    </div>
  )
}

interface AuditSearch {
  entity?: string
  action?: Action
  since?: string
  until?: string
  actor_id?: string
  page?: number
}

/** Every change, for those who administer: filtered in the URL. */
export function AuditAdmin() {
  const search = useSearch({ strict: false }) as AuditSearch
  const navigate = useNavigate()
  const [open, setOpen] = useState<string | null>(null)
  const set = (changes: Partial<AuditSearch>) =>
    navigate({ to: ".", search: (prev: Record<string, unknown>) => ({ ...prev, ...changes, page: changes.page }) as never, replace: true })
  const page = Number(search.page) || 1
  const query = { entity: search.entity, action: search.action, since: search.since, until: search.until, actor_id: search.actor_id, page, per_page: PER_PAGE }
  const list = useQuery({
    queryKey: ["audit", query],
    queryFn: ({ signal }) => (api as unknown as { audit: { list(q: object, o: object): Promise<EntryPage> } }).audit.list(query, { signal }),
    placeholderData: keepPreviousData,
  })
  const audited = Object.values(resources as unknown as Record<string, ResourceMeta>).filter((m) => m.history)
  const filter = "w-auto min-w-40 font-semibold"
  return (
    <div className="flex flex-col gap-4">
      <PageHeader title={t("audit")} description={t("auditHint")} />
      <div className="flex flex-col gap-4 rounded-xl border border-border bg-card p-5">
        <div className="flex flex-wrap items-center gap-2">
          <Select value={search.entity ?? "__all"} onValueChange={(v) => set({ entity: v === "__all" ? undefined : v })}>
            <SelectTrigger className={filter}>
              <span className="font-medium text-muted-foreground">{t("auditWhat")}:</span>
              <SelectValue />
            </SelectTrigger>
            <SelectContent position="popper">
              <SelectItem value="__all">{capitalize(t("all"))}</SelectItem>
              {audited.map((m) => (
                <SelectItem key={m.history!.entity} value={m.history!.entity}>
                  {m.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <Select value={search.action ?? "__all"} onValueChange={(v) => set({ action: v === "__all" ? undefined : (v as Action) })}>
            <SelectTrigger className={filter}>
              <span className="font-medium text-muted-foreground">{t("auditAction")}:</span>
              <SelectValue />
            </SelectTrigger>
            <SelectContent position="popper">
              <SelectItem value="__all">{capitalize(t("all"))}</SelectItem>
              {(Object.keys(ACTIONS) as Action[]).map((a) => (
                <SelectItem key={a} value={a}>
                  {t(`auditAction_${a}`)}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <label className="flex items-center gap-2 text-sm font-medium text-muted-foreground">
            {t("auditSince")}
            <Input type="date" className="w-auto" value={search.since ?? ""} onChange={(e) => set({ since: e.target.value || undefined })} />
          </label>
          <label className="flex items-center gap-2 text-sm font-medium text-muted-foreground">
            {t("auditUntil")}
            <Input type="date" className="w-auto" value={search.until ?? ""} onChange={(e) => set({ until: e.target.value || undefined })} />
          </label>
          {search.actor_id && (
            <Button variant="ghost" onClick={() => set({ actor_id: undefined })}>
              {t("clearFilters")}
            </Button>
          )}
        </div>
        {list.isError ? (
          <ErrorState error={list.error} onRetry={() => list.refetch()} />
        ) : (
          <Table>
            <TableHeader>
              <TableRow>
                {[t("auditWhen"), t("auditWho"), t("auditAction"), t("auditRecord"), t("auditFields")].map((h) => (
                  <TableHead key={h} className="text-xs font-semibold tracking-wider text-muted-foreground uppercase">
                    {h}
                  </TableHead>
                ))}
                <TableHead className="w-0" />
              </TableRow>
            </TableHeader>
            <TableBody>
              {list.isPending &&
                Array.from({ length: 5 }, (_, i) => (
                  <TableRow key={i}>
                    <TableCell colSpan={6}>
                      <Skeleton className="h-9 w-full" />
                    </TableCell>
                  </TableRow>
                ))}
              {list.data?.items.length === 0 && (
                <TableRow>
                  <TableCell colSpan={6} className="py-12 text-center text-sm text-muted-foreground">
                    {t("noChanges")}
                  </TableCell>
                </TableRow>
              )}
              {list.data?.items.map((e) => {
                const meta = metaOfEntity(e.entity)
                const A = ACTIONS[e.action]
                const names = Object.keys(e.changes).map((n) => fieldOf(meta, n).label)
                return [
                  <TableRow key={e.id} className="cursor-pointer" onClick={() => setOpen(open === e.id ? null : e.id)}>
                    <TableCell className="whitespace-nowrap text-muted-foreground" title={when(e.at)}>
                      {when(e.at)}
                    </TableCell>
                    <TableCell>
                      <button
                        type="button"
                        className="flex items-center gap-2 font-semibold text-foreground hover:underline"
                        onClick={(ev) => {
                          ev.stopPropagation()
                          if (e.actor.id) set({ actor_id: e.actor.id })
                        }}
                      >
                        <ActorBadge actor={e.actor} />
                        {e.actor.name}
                      </button>
                    </TableCell>
                    <TableCell>
                      <Badge variant="secondary" className={cn("gap-1", A.tone)}>
                        <A.icon className="size-3" /> {t(`auditAction_${e.action}`)}
                      </Badge>
                    </TableCell>
                    <TableCell>
                      {meta ? (
                        <Link to={`/${meta.name}/${e.record_id}` as never} className="font-medium hover:underline" onClick={(ev) => ev.stopPropagation()}>
                          {meta.singular} <span className="font-mono text-xs text-muted-foreground">{e.record_id.slice(0, 8)}</span>
                        </Link>
                      ) : (
                        <span className="font-mono text-xs">{e.entity}</span>
                      )}
                    </TableCell>
                    <TableCell className="max-w-72 truncate text-muted-foreground">{names.join(", ") || "—"}</TableCell>
                    <TableCell>
                      <ChevronDown className={cn("size-4 text-muted-foreground transition-transform", open === e.id && "rotate-180")} />
                    </TableCell>
                  </TableRow>,
                  open === e.id && (
                    <TableRow key={`${e.id}-changes`} className="hover:bg-transparent">
                      <TableCell colSpan={6} className="pt-0">
                        <Changes meta={meta} entry={e} />
                      </TableCell>
                    </TableRow>
                  ),
                ]
              })}
            </TableBody>
          </Table>
        )}
        {list.data && list.data.total_pages > 1 && <Pager page={page} pages={list.data.total_pages} onPage={(p) => set({ page: p })} />}
      </div>
    </div>
  )
}
